{"category_edits":[{"category":"learning_objective","rationale":"Average the existing pointwise logistic loss within each nonempty sequence, then equally across sequences. This may better match equal-user evaluation by reducing the influence of long histories across all four datasets. Architecture, sampling, optimizer, training settings and prediction remain unchanged. Require the mandated data directory environment variable.","edits":[{"find":"    loss = nn.functional.softplus(-pos_scores) + nn.functional.softplus(neg_scores)
    return (loss * mask).sum() / mask.sum().clamp(min=1.0)","replace":"    loss = nn.functional.softplus(-pos_scores) + nn.functional.softplus(neg_scores)
    valid_counts = mask.sum(dim=1)
    sequence_losses = (loss * mask).sum(dim=1) / valid_counts.clamp(min=1.0)
    nonempty = (valid_counts > 0).to(dtype=loss.dtype)
    return (sequence_losses * nonempty).sum() / nonempty.sum().clamp(min=1.0)"},{"find":"DATA_DIR = os.environ.get("GAGC_DATA_DIR", "./input/trainval")","replace":"DATA_DIR = os.environ['GAGC_DATA_DIR']"}]}],"change_summary":"Apply equal-sequence weighting to the existing logistic objective across all four category models and enforce GAGC_DATA_DIR. Predictor and checkpoint shapes remain unchanged."}
